import { useEffect, useMemo, useRef, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "react-router-dom";
import toast from "react-hot-toast";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faArrowDownWideShort,
  faArrowUpWideShort,
  faBoxOpen,
  faCheck,
  faChevronLeft,
  faChevronRight,
  faEllipsis,
  faFolder,
  faPenToSquare,
  faRotateLeft,
  faTag,
  faTriangleExclamation,
  faXmark,
} from "@fortawesome/free-solid-svg-icons";
import { faEye, faTrashCan } from "@fortawesome/free-regular-svg-icons";
import ConfirmationModal from "../components/ConfirmationModal";
import ProductForm from "../components/ProductForm";
import Tooltip from "../components/Tooltip";
import { useI18n } from "../context/I18nContext";
import api from "../services/api";

function findTreeNodeById(nodes, id) {
  for (const node of nodes) {
    if (node.id === id) {
      return node;
    }

    if (node.children?.length) {
      const found = findTreeNodeById(node.children, id);
      if (found) {
        return found;
      }
    }
  }

  return null;
}

function findPathToCategory(nodes, id, path = []) {
  for (const node of nodes) {
    const nextPath = [...path, node];
    if (node.id === id) {
      return nextPath;
    }

    if (node.children?.length) {
      const found = findPathToCategory(node.children, id, nextPath);
      if (found) {
        return found;
      }
    }
  }

  return null;
}

function buildPagination(currentPage, lastPage) {
  if (!lastPage || lastPage <= 1) {
    return [];
  }

  const pages = new Set([
    1,
    lastPage,
    currentPage - 1,
    currentPage,
    currentPage + 1,
  ]);
  const normalized = [...pages]
    .filter((page) => page >= 1 && page <= lastPage)
    .sort((a, b) => a - b);

  const withEllipsis = [];
  normalized.forEach((page, index) => {
    const previous = normalized[index - 1];
    if (index > 0 && page - previous > 1) {
      withEllipsis.push(`ellipsis-${previous}-${page}`);
    }
    withEllipsis.push(page);
  });

  return withEllipsis;
}

function ProductBoxIcon({ className = "h-4 w-4" }) {
  return <FontAwesomeIcon icon={faBoxOpen} className={className} />;
}

function CategoryTagIcon({ className = "h-4 w-4" }) {
  return <FontAwesomeIcon icon={faTag} className={className} />;
}

function Products() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { t, language } = useI18n();

  const [selectedCategoryId, setSelectedCategoryId] = useState(null);
  const [expandedIds, setExpandedIds] = useState(new Set());
  const [openActionMenuCategoryId, setOpenActionMenuCategoryId] =
    useState(null);
  const actionButtonRefs = useRef({});
  const actionMenuRef = useRef(null);
  const [actionMenuPosition, setActionMenuPosition] = useState({
    top: 0,
    left: 0,
    maxHeight: 240,
  });

  const [showProductModal, setShowProductModal] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);
  const [showDeleteProductModal, setShowDeleteProductModal] = useState(false);
  const [productToDelete, setProductToDelete] = useState(null);

  const [showCategoryModal, setShowCategoryModal] = useState(false);
  const [editingCategory, setEditingCategory] = useState(null);
  const [showDeleteCategoryModal, setShowDeleteCategoryModal] = useState(false);
  const [categoryToDelete, setCategoryToDelete] = useState(null);
  const [categoryForm, setCategoryForm] = useState({
    name: "",
    description: "",
    parent_id: "",
  });

  const [page, setPage] = useState(1);
  const [perPage, setPerPage] = useState(10);
  const [quickGoPage, setQuickGoPage] = useState("");
  const [searchTerm, setSearchTerm] = useState("");
  const [sortBy, setSortBy] = useState("name");
  const [sortDirection, setSortDirection] = useState("asc");

  const [createdFrom, setCreatedFrom] = useState("");
  const [createdTo, setCreatedTo] = useState("");
  const [minPrice, setMinPrice] = useState("");
  const [maxPrice, setMaxPrice] = useState("");

  const { data: categoriesResponse, isLoading: loadingCategories } = useQuery({
    queryKey: ["categories"],
    queryFn: async () => {
      const response = await api.get("/categories");
      return response.data;
    },
  });

  const categoryTree = categoriesResponse?.tree || [];

  useEffect(() => {
    if (!selectedCategoryId && categoryTree.length > 0) {
      setSelectedCategoryId(categoryTree[0].id);
    }
  }, [categoryTree, selectedCategoryId]);

  const selectedNode = selectedCategoryId
    ? findTreeNodeById(categoryTree, selectedCategoryId)
    : null;

  const selectedCategoryPath = useMemo(() => {
    if (!selectedCategoryId) {
      return [];
    }

    return findPathToCategory(categoryTree, selectedCategoryId) || [];
  }, [categoryTree, selectedCategoryId]);

  const selectedCategoryLevel = selectedCategoryPath.length;
  const canCreateSubCategory =
    Boolean(selectedNode) &&
    selectedCategoryLevel > 0 &&
    selectedCategoryLevel < 3;
  const canCreateProduct = Boolean(selectedNode) && selectedCategoryLevel === 3;

  const { data: productsResponse, isLoading: loadingProducts } = useQuery({
    queryKey: [
      "products",
      selectedCategoryId,
      page,
      perPage,
      searchTerm,
      createdFrom,
      createdTo,
      minPrice,
      maxPrice,
      sortBy,
      sortDirection,
    ],
    queryFn: async () => {
      const response = await api.get("/products", {
        params: {
          category_id: selectedCategoryId || undefined,
          include_descendants: true,
          search: searchTerm || undefined,
          per_page: perPage,
          page,
          created_from: createdFrom || undefined,
          created_to: createdTo || undefined,
          min_price: minPrice !== "" ? Number(minPrice) : undefined,
          max_price: maxPrice !== "" ? Number(maxPrice) : undefined,
          sort_by: sortBy,
          sort_direction: sortDirection,
        },
      });
      return response.data;
    },
    enabled: !!selectedCategoryId,
  });

  const paginatedProducts = productsResponse?.data || [];
  const displayedProducts = paginatedProducts;

  const allCategoryProductsCount = useMemo(() => {
    const walk = (nodes) =>
      nodes.reduce((sum, node) => {
        return sum + (node.products_count || 0) + walk(node.children || []);
      }, 0);

    return walk(categoryTree);
  }, [categoryTree]);

  const hasActiveProductFilters =
    Boolean(searchTerm) ||
    Boolean(createdFrom) ||
    Boolean(createdTo) ||
    minPrice !== "" ||
    maxPrice !== "";

  const handleQuickGoToPage = () => {
    const raw = quickGoPage.trim();
    if (!raw) {
      return;
    }

    const targetPage = Number(raw);
    if (!Number.isInteger(targetPage) || targetPage < 1) {
      toast.error(t("invalidPageNumber"));
      return;
    }

    const lastPage = productsResponse?.last_page || 1;
    setPage(Math.min(targetPage, lastPage));
    setQuickGoPage("");
  };

  const createProductMutation = useMutation({
    mutationFn: async (rawData) => {
      const payload = {
        category_id: Number(rawData.category_id),
        name: rawData.name,
        barcode: rawData.barcode || null,
        description: rawData.description || null,
        unit_id: rawData.unit_id ? Number(rawData.unit_id) : null,
        provider: rawData.provider || null,
        purchase_price: Number(rawData.purchase_price || 0),
        sale_price: Number(rawData.sale_price || 0),
        quantity: Number(rawData.quantity || 0),
        expiry_date: rawData.expiry_date || null,
        min_stock_alert: Number(rawData.min_stock_alert || 5),
        min_expiry_alert: Number(rawData.min_expiry_alert || 7),
      };

      const response = await api.post("/products", payload);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      queryClient.invalidateQueries({ queryKey: ["products"] });
      setShowProductModal(false);
      setEditingProduct(null);
      toast.success(t("productCreatedSuccessfully"));
    },
    onError: (error) => {
      const message =
        error.response?.data?.message ||
        (error.response?.data?.errors
          ? Object.values(error.response.data.errors).flat().join(", ")
          : null) ||
        t("errorCreatingProduct");
      toast.error(message);
    },
  });

  const updateProductMutation = useMutation({
    mutationFn: async ({ id, rawData }) => {
      const payload = {
        category_id: Number(rawData.category_id),
        name: rawData.name,
        barcode: rawData.barcode || null,
        description: rawData.description || null,
        unit_id: rawData.unit_id ? Number(rawData.unit_id) : null,
        provider: rawData.provider || null,
        purchase_price: Number(rawData.purchase_price || 0),
        sale_price: Number(rawData.sale_price || 0),
        quantity: Number(rawData.quantity || 0),
        expiry_date: rawData.expiry_date || null,
        min_stock_alert: Number(rawData.min_stock_alert || 5),
        min_expiry_alert: Number(rawData.min_expiry_alert || 7),
      };

      const response = await api.put(`/products/${id}`, payload);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      queryClient.invalidateQueries({ queryKey: ["products"] });
      setShowProductModal(false);
      setEditingProduct(null);
      toast.success(t("productUpdatedSuccessfully"));
    },
    onError: (error) => {
      const message =
        error.response?.data?.message ||
        (error.response?.data?.errors
          ? Object.values(error.response.data.errors).flat().join(", ")
          : null) ||
        t("errorUpdatingProduct");
      toast.error(message);
    },
  });

  const deleteProductMutation = useMutation({
    mutationFn: async (id) => {
      const response = await api.delete(`/products/${id}`);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      queryClient.invalidateQueries({ queryKey: ["products"] });
      toast.success(t("productDeletedSuccessfully"));
    },
    onError: (error) => {
      const message =
        error.response?.data?.message || t("errorDeletingProduct");
      toast.error(message);
    },
  });

  const createCategoryMutation = useMutation({
    mutationFn: async (payload) => {
      const response = await api.post("/categories", payload);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      setShowCategoryModal(false);
      setEditingCategory(null);
      setCategoryForm({ name: "", description: "", parent_id: "" });
      toast.success(t("categoryCreatedSuccessfully"));
    },
    onError: (error) => {
      toast.error(error.response?.data?.message || t("errorCreatingCategory"));
    },
  });

  const updateCategoryMutation = useMutation({
    mutationFn: async ({ id, payload }) => {
      const response = await api.put(`/categories/${id}`, payload);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      setShowCategoryModal(false);
      setEditingCategory(null);
      setCategoryForm({ name: "", description: "", parent_id: "" });
      toast.success(t("categoryUpdatedSuccessfully"));
    },
    onError: (error) => {
      toast.error(error.response?.data?.message || t("errorUpdatingCategory"));
    },
  });

  const deleteCategoryMutation = useMutation({
    mutationFn: async (id) => {
      const response = await api.delete(`/categories/${id}`);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["categories"] });
      toast.success(t("categoryDeletedSuccessfully"));
    },
    onError: (error) => {
      toast.error(error.response?.data?.message || t("errorDeletingCategory"));
    },
  });

  const handleProductSubmit = (formData) => {
    if (editingProduct) {
      updateProductMutation.mutate({
        id: editingProduct.id,
        rawData: formData,
      });
      return;
    }

    createProductMutation.mutate(formData);
  };

  const handleEditProduct = (product) => {
    setEditingProduct(product);
    setShowProductModal(true);
  };

  const handleDeleteProduct = (id) => {
    setProductToDelete(id);
    setShowDeleteProductModal(true);
  };

  const confirmDeleteProduct = () => {
    if (!productToDelete) {
      return;
    }

    deleteProductMutation.mutate(productToDelete);
    setShowDeleteProductModal(false);
    setProductToDelete(null);
  };

  const handleCloseProductModal = () => {
    setShowProductModal(false);
    setEditingProduct(null);
  };

  const handleSelectCategory = (id) => {
    setSelectedCategoryId(id);
    setSearchTerm("");
    setPage(1);

    const path = findPathToCategory(categoryTree, id) || [];
    const node = findTreeNodeById(categoryTree, id);
    const hasChildren = (node?.children?.length || 0) > 0;
    const ids = hasChildren
      ? path.map((pathNode) => pathNode.id)
      : path.slice(0, -1).map((pathNode) => pathNode.id);

    setExpandedIds(new Set(ids));
  };

  const openCreateCategory = (parentCategoryId) => {
    if (!parentCategoryId) {
      setEditingCategory(null);
      setCategoryForm({
        name: "",
        description: "",
        parent_id: "",
      });
      setShowCategoryModal(true);
      setOpenActionMenuCategoryId(null);
      return;
    }

    const parentPath = findPathToCategory(categoryTree, parentCategoryId) || [];
    if (parentPath.length >= 3) {
      toast.error(t("maxThreeLevelsMessage"));
      setOpenActionMenuCategoryId(null);
      return;
    }

    setEditingCategory(null);
    setCategoryForm({
      name: "",
      description: "",
      parent_id: parentCategoryId ? String(parentCategoryId) : "",
    });
    setShowCategoryModal(true);
    setOpenActionMenuCategoryId(null);
  };

  const openEditCategory = (categoryId) => {
    const node = findTreeNodeById(categoryTree, categoryId);
    if (!node) {
      return;
    }

    setEditingCategory(node);
    setCategoryForm({
      name: node.name || "",
      description: node.description || "",
      parent_id: node.parent_id ? String(node.parent_id) : "",
    });
    setShowCategoryModal(true);
    setOpenActionMenuCategoryId(null);
  };

  const openDeleteCategory = (categoryId) => {
    setCategoryToDelete(categoryId);
    setShowDeleteCategoryModal(true);
    setOpenActionMenuCategoryId(null);
  };

  const confirmDeleteCategory = () => {
    if (!categoryToDelete) {
      return;
    }

    const node = findTreeNodeById(categoryTree, categoryToDelete);

    if (node?.children?.length) {
      toast.error(t("cannotDeleteCategoryWithChildren"));
      setShowDeleteCategoryModal(false);
      setCategoryToDelete(null);
      return;
    }

    if ((node?.products_count || 0) > 0) {
      toast.error(t("cannotDeleteCategoryWithProducts"));
      setShowDeleteCategoryModal(false);
      setCategoryToDelete(null);
      return;
    }

    deleteCategoryMutation.mutate(categoryToDelete);
    setShowDeleteCategoryModal(false);
    setCategoryToDelete(null);
  };

  const submitCategory = (event) => {
    event.preventDefault();

    const payload = {
      name: categoryForm.name,
      description: categoryForm.description || null,
      parent_id: categoryForm.parent_id ? Number(categoryForm.parent_id) : null,
    };

    if (editingCategory) {
      updateCategoryMutation.mutate({ id: editingCategory.id, payload });
      return;
    }

    createCategoryMutation.mutate(payload);
  };

  const openCreateProductForCategory = (categoryId) => {
    const node = findTreeNodeById(categoryTree, categoryId);
    if (!node) {
      return;
    }

    const path = findPathToCategory(categoryTree, categoryId) || [];
    if (path.length !== 3) {
      toast.error(t("leafOnlyProducts"));
      setOpenActionMenuCategoryId(null);
      return;
    }

    setSelectedCategoryId(node.id);
    setEditingProduct(null);
    setShowProductModal(true);
    setOpenActionMenuCategoryId(null);
  };

  const getStockStatus = (product) => {
    if (Number(product.quantity) <= Number(product.min_stock_alert || 0)) {
      return {
        text: t("lowStock"),
        color: "bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-400",
      };
    }

    return {
      text: t("available"),
      color:
        "bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-400",
    };
  };

  const toggleExpand = (id) => {
    setExpandedIds((previous) => {
      const path = findPathToCategory(categoryTree, id) || [];
      if (!path.length) {
        return previous;
      }

      if (previous.has(id)) {
        return new Set(path.slice(0, -1).map((pathNode) => pathNode.id));
      }

      return new Set(path.map((pathNode) => pathNode.id));
    });
  };

  const updateActionMenuPosition = (categoryId) => {
    const trigger = actionButtonRefs.current[categoryId];
    if (!trigger || typeof window === "undefined") {
      return;
    }

    const rect = trigger.getBoundingClientRect();
    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;
    const menuWidth = 176;
    const viewportGap = 8;
    const menuOffset = 4;
    const measuredHeight = actionMenuRef.current?.offsetHeight || 176;

    const spaceBelow = viewportHeight - rect.bottom - viewportGap;
    const spaceAbove = rect.top - viewportGap;
    const shouldOpenUp = spaceBelow < measuredHeight && spaceAbove > spaceBelow;

    const maxHeight = Math.max(
      120,
      (shouldOpenUp ? spaceAbove : spaceBelow) - menuOffset,
    );

    let left = rect.right - menuWidth;
    left = Math.max(
      viewportGap,
      Math.min(left, viewportWidth - menuWidth - viewportGap),
    );

    const top = shouldOpenUp
      ? Math.max(
          viewportGap,
          rect.top - Math.min(measuredHeight, maxHeight) - menuOffset,
        )
      : Math.min(
          viewportHeight - viewportGap - Math.min(measuredHeight, maxHeight),
          rect.bottom + menuOffset,
        );

    setActionMenuPosition({ top, left, maxHeight });
  };

  useEffect(() => {
    if (!openActionMenuCategoryId) {
      return undefined;
    }

    const handleLayoutChange = () => {
      updateActionMenuPosition(openActionMenuCategoryId);
    };

    const handlePointerDown = (event) => {
      const menuElement = actionMenuRef.current;
      const triggerElement = actionButtonRefs.current[openActionMenuCategoryId];
      const target = event.target;

      if (menuElement?.contains(target) || triggerElement?.contains(target)) {
        return;
      }

      setOpenActionMenuCategoryId(null);
    };

    handleLayoutChange();
    window.addEventListener("resize", handleLayoutChange);
    window.addEventListener("scroll", handleLayoutChange, true);
    document.addEventListener("pointerdown", handlePointerDown);

    return () => {
      window.removeEventListener("resize", handleLayoutChange);
      window.removeEventListener("scroll", handleLayoutChange, true);
      document.removeEventListener("pointerdown", handlePointerDown);
    };
  }, [openActionMenuCategoryId]);

  const renderTree = (nodes, level = 1) => {
    return nodes.map((node, index) => {
      const hasChildren = node.children?.length > 0;
      const isExpanded = expandedIds.has(node.id);
      const isSelected = selectedCategoryId === node.id;
      const isLast = index === nodes.length - 1;
      const canAddCategoryAtLevel = level < 3;
      const canAddProductAtLevel = level === 3;
      const indentStep = 38;
      const rowHeight = 36;
      const iconSize = 24;
      const nodeStart = Math.max(
        0,
        (level - 1) * indentStep - (level === 3 ? 14 : 0),
      );
      const nodeCenter = nodeStart + iconSize / 2;
      const parentCenter = nodeCenter - indentStep;
      const midY = rowHeight / 2;
      const connectorGap = 2;
      const parentToNodeWidth = Math.max(
        10,
        nodeStart - connectorGap - parentCenter,
      );
      const childBranchStub = 10;

      return (
        <div key={node.id} className="relative pb-0">
          {hasChildren && isExpanded && (
            <>
              <span
                className="pointer-events-none absolute z-0 h-px bg-sky-600/90 dark:bg-sky-300/90"
                style={{
                  insetInlineStart: `${nodeCenter}px`,
                  top: `${midY}px`,
                  width: `${childBranchStub}px`,
                }}
              />
            </>
          )}

          {level > 1 && (
            <>
              <span
                className="pointer-events-none absolute z-0 w-px bg-sky-600/80 dark:bg-sky-400/80"
                style={{
                  insetInlineStart: `${parentCenter}px`,
                  top: 0,
                  height: isLast ? `${midY}px` : "100%",
                }}
              />
              <span
                className="pointer-events-none absolute z-0 h-px bg-sky-600/80 dark:bg-sky-400/80"
                style={{
                  top: `${midY}px`,
                  insetInlineStart: `${parentCenter}px`,
                  width: `${parentToNodeWidth}px`,
                }}
              />
            </>
          )}

          <div
            className={`relative flex items-center justify-between gap-1 ${
              openActionMenuCategoryId === node.id ? "z-[130]" : "z-10"
            }`}
            style={{
              minHeight: `${rowHeight}px`,
              marginInlineStart: `${nodeStart}px`,
              width: `calc(100% - ${nodeStart}px)`,
            }}
          >
            <button
              type="button"
              onClick={() => handleSelectCategory(node.id)}
              className={`flex min-w-0 items-center gap-1.5 rounded-md px-0.5 py-0.5 text-start transition-colors ${
                isSelected
                  ? "bg-primary-50 text-primary-800 dark:bg-primary-900/25 dark:text-primary-100"
                  : "hover:bg-gray-50/80 dark:hover:bg-gray-800/80"
              }`}
            >
              <span
                className={`inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-sm text-gray-900 dark:text-gray-100 ${
                  hasChildren
                    ? "bg-gray-100/80 hover:bg-gray-200/80 dark:bg-gray-700/80 dark:hover:bg-gray-600/80"
                    : "bg-gray-100/60 dark:bg-gray-700/60"
                }`}
                onClick={(event) => {
                  event.stopPropagation();
                  if (hasChildren) {
                    toggleExpand(node.id);
                  }
                }}
              >
                <FontAwesomeIcon icon={faFolder} className="h-4 w-4" />
              </span>
              <span
                dir="auto"
                className="truncate text-[15px] font-semibold leading-tight"
              >
                {node.name}
              </span>
            </button>

            <div className="flex shrink-0 items-center gap-1">
              <span className="text-[10px] px-1.5 py-0 rounded-full bg-primary-100 dark:bg-primary-900/40 text-primary-700 dark:text-primary-200">
                {node.products_count || 0}
              </span>
              <Tooltip label={t("actions")}>
                <span
                  ref={(element) => {
                    actionButtonRefs.current[node.id] = element;
                  }}
                  role="button"
                  tabIndex={0}
                  className="inline-flex h-6 w-6 cursor-pointer items-center justify-center rounded-md bg-gray-100/90 dark:bg-gray-800/90 text-[11px]"
                  onClick={(event) => {
                    event.stopPropagation();
                    setOpenActionMenuCategoryId((previous) =>
                      previous === node.id ? null : node.id,
                    );
                  }}
                  onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                      event.preventDefault();
                      event.stopPropagation();
                      setOpenActionMenuCategoryId((previous) =>
                        previous === node.id ? null : node.id,
                      );
                    }
                  }}
                >
                  <FontAwesomeIcon icon={faEllipsis} className="h-3 w-3" />
                </span>
              </Tooltip>
            </div>

            {openActionMenuCategoryId === node.id && (
              <div
                ref={actionMenuRef}
                className="fixed z-[120] w-44 rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 shadow-lg p-1 overflow-y-auto"
                style={{
                  top: `${actionMenuPosition.top}px`,
                  left: `${actionMenuPosition.left}px`,
                  maxHeight: `${actionMenuPosition.maxHeight}px`,
                }}
              >
                {canAddCategoryAtLevel ? (
                  <button
                    type="button"
                    className="w-full text-start px-3 py-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800 text-sm"
                    onClick={() => openCreateCategory(node.id)}
                  >
                    <span className="inline-flex items-center gap-2">
                      <CategoryTagIcon className="h-3.5 w-3.5" />
                      {t("addCategory")}
                    </span>
                  </button>
                ) : null}
                {canAddProductAtLevel ? (
                  <button
                    type="button"
                    className="w-full text-start px-3 py-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800 text-sm"
                    onClick={() => openCreateProductForCategory(node.id)}
                  >
                    <span className="inline-flex items-center gap-2">
                      <ProductBoxIcon className="h-3.5 w-3.5" />
                      {t("addProduct")}
                    </span>
                  </button>
                ) : null}
                <button
                  type="button"
                  className="w-full text-start px-3 py-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800 text-sm"
                  onClick={() => openEditCategory(node.id)}
                >
                  {t("editCategory")}
                </button>
                <button
                  type="button"
                  className="w-full text-start px-3 py-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800 text-sm"
                  onClick={() => openDeleteCategory(node.id)}
                >
                  {t("delete")}
                </button>
              </div>
            )}
          </div>

          {hasChildren && isExpanded && (
            <div className="space-y-0">
              {renderTree(node.children, level + 1)}
            </div>
          )}
        </div>
      );
    });
  };

  if (loadingCategories) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600" />
          <p className="mt-4 text-gray-600 dark:text-gray-400">
            {t("loading")}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="page-header-section">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <h2 className="text-3xl font-bold text-gray-900 dark:text-white">
              {t("manageProducts")}
            </h2>
            <p className="page-header-description mt-1">
              {t("productsCount")}: {allCategoryProductsCount}
            </p>
          </div>
          <div className="page-header-actions">
            <button
              onClick={() => {
                if (!selectedNode) {
                  toast.error(t("selectCategoryFirst"));
                  return;
                }

                if (canCreateProduct) {
                  setEditingProduct(null);
                  setShowProductModal(true);
                  return;
                }

                toast.error(t("leafOnlyProducts"));
              }}
              className="btn-primary rounded-none flex items-center gap-2"
              aria-label={t("addProduct")}
            >
              <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-white/20">
                <ProductBoxIcon className="h-3.5 w-3.5" />
              </span>
            </button>
          </div>
        </div>
      </div>

      <div className="card space-y-3">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-3">
          <div className="lg:col-span-2">
            <input
              type="text"
              value={searchTerm}
              onChange={(event) => {
                setSearchTerm(event.target.value);
                setPage(1);
              }}
              placeholder={t("searchPlaceholder")}
              className="input"
            />
          </div>
          <select
            value={sortBy}
            onChange={(event) => {
              setSortBy(event.target.value);
              setPage(1);
            }}
            className="input h-9 py-0"
          >
            <option value="name">{t("productName")}</option>
            <option value="purchase_price">{t("purchasePrice")}</option>
            <option value="sale_price">{t("salePrice")}</option>
            <option value="quantity">{t("quantity")}</option>
            <option value="created_at">{t("createdAt")}</option>
          </select>
          <Tooltip label={t("sort")}>
            <button
              type="button"
              onClick={() => {
                setSortDirection((previous) =>
                  previous === "asc" ? "desc" : "asc",
                );
                setPage(1);
              }}
              className="inline-flex h-9 w-9 items-center justify-center rounded-none border border-gray-300 dark:border-gray-700"
              aria-label={t("sort")}
            >
              {sortDirection === "asc" ? (
                <FontAwesomeIcon
                  icon={faArrowUpWideShort}
                  className="h-4 w-4"
                />
              ) : (
                <FontAwesomeIcon
                  icon={faArrowDownWideShort}
                  className="h-4 w-4"
                />
              )}
            </button>
          </Tooltip>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-5 gap-3">
          <input
            type="date"
            value={createdFrom}
            onChange={(event) => {
              setCreatedFrom(event.target.value);
              setPage(1);
            }}
            className="input"
            aria-label={t("dateAddedAfter")}
          />
          <input
            type="date"
            value={createdTo}
            onChange={(event) => {
              setCreatedTo(event.target.value);
              setPage(1);
            }}
            className="input"
            aria-label={t("dateAddedBefore")}
          />
          <input
            type="number"
            step="0.01"
            value={minPrice}
            onChange={(event) => {
              setMinPrice(event.target.value);
              setPage(1);
            }}
            placeholder={t("minPrice")}
            className="input"
          />
          <input
            type="number"
            step="0.01"
            value={maxPrice}
            onChange={(event) => {
              setMaxPrice(event.target.value);
              setPage(1);
            }}
            placeholder={t("maxPrice")}
            className="input"
          />
          <div className="flex items-center justify-end">
            <Tooltip label={t("reset")}>
              <button
                type="button"
                className="inline-flex h-9 w-9 items-center justify-center rounded-none border border-gray-300 dark:border-gray-700"
                onClick={() => {
                  setSearchTerm("");
                  setCreatedFrom("");
                  setCreatedTo("");
                  setMinPrice("");
                  setMaxPrice("");
                  setQuickGoPage("");
                  setPage(1);
                }}
                aria-label={t("reset")}
              >
                <FontAwesomeIcon icon={faRotateLeft} className="h-4 w-4" />
              </button>
            </Tooltip>
          </div>
        </div>
      </div>

      {categoryTree.length > 0 ? (
        <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
          <div className="card xl:col-span-4 space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                {t("categoryTree")}
              </h3>
              <Tooltip label={t("addCategory")}>
                <button
                  type="button"
                  className="btn-secondary rounded-none text-sm"
                  onClick={() => openCreateCategory(null)}
                  aria-label={t("addCategory")}
                >
                  <span className="inline-flex h-5 w-5 items-center justify-center">
                    <CategoryTagIcon />
                  </span>
                </button>
              </Tooltip>
            </div>
            <div
              dir={language === "ar" ? "rtl" : "ltr"}
              className="max-h-[620px] overflow-auto pe-1 space-y-1"
            >
              {renderTree(categoryTree)}
            </div>
          </div>

          <div className="card xl:col-span-8 space-y-4">
            {selectedNode ? (
              <>
                <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                  <div>
                    <h3 className="text-2xl font-bold text-gray-900 dark:text-white">
                      {selectedNode.name}
                    </h3>
                    <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                      {t("productsCount")}: {selectedNode.products_count || 0}
                    </p>
                  </div>
                  <Tooltip
                    label={
                      canCreateProduct ? t("addProduct") : t("addCategory")
                    }
                  >
                    <button
                      onClick={() => {
                        if (canCreateProduct) {
                          setEditingProduct(null);
                          setShowProductModal(true);
                          return;
                        }

                        if (canCreateSubCategory) {
                          openCreateCategory(selectedNode.id);
                          return;
                        }

                        toast.error(t("leafOnlyProducts"));
                      }}
                      className="btn-primary rounded-none inline-flex items-center justify-center"
                      aria-label={
                        canCreateProduct ? t("addProduct") : t("addCategory")
                      }
                    >
                      <span className="inline-flex h-5 w-5 items-center justify-center">
                        {canCreateProduct ? (
                          <ProductBoxIcon />
                        ) : (
                          <CategoryTagIcon />
                        )}
                      </span>
                    </button>
                  </Tooltip>
                </div>

                <div className="overflow-hidden rounded border border-gray-200 dark:border-gray-700">
                  <div className="overflow-x-auto">
                    <table className="min-w-full text-sm">
                      <thead className="bg-gray-50 dark:bg-gray-800">
                        <tr>
                          <th className="px-4 py-2 text-start font-semibold">
                            {t("productName")}
                          </th>
                          <th className="px-4 py-2 text-start font-semibold">
                            {t("salePrice")}
                          </th>
                          <th className="px-4 py-2 text-start font-semibold">
                            {t("quantity")}
                          </th>
                          <th className="px-4 py-2 text-start font-semibold">
                            {t("status")}
                          </th>
                          <th className="px-4 py-2 text-start font-semibold">
                            {t("actions")}
                          </th>
                        </tr>
                      </thead>
                      <tbody>
                        {loadingProducts ? (
                          <tr>
                            <td
                              colSpan={5}
                              className="px-4 py-8 text-center text-gray-500 dark:text-gray-400"
                            >
                              {t("loading")}
                            </td>
                          </tr>
                        ) : displayedProducts.length > 0 ? (
                          displayedProducts.map((product) => {
                            const stockStatus = getStockStatus(product);
                            return (
                              <tr
                                key={product.id}
                                className="border-t border-gray-200 dark:border-gray-700"
                              >
                                <td className="px-4 py-2 font-medium">
                                  {product.name}
                                </td>
                                <td className="px-4 py-2">
                                  {Number(product.sale_price || 0).toFixed(2)}
                                </td>
                                <td className="px-4 py-2">
                                  {product.quantity || 0}
                                </td>
                                <td className="px-4 py-2">
                                  <Tooltip label={stockStatus.text}>
                                    <span
                                      className={`inline-flex h-7 w-7 items-center justify-center rounded-full ${stockStatus.color}`}
                                      aria-label={stockStatus.text}
                                    >
                                      {stockStatus.text === t("available") ? (
                                        <FontAwesomeIcon
                                          icon={faCheck}
                                          className="h-3.5 w-3.5"
                                        />
                                      ) : (
                                        <FontAwesomeIcon
                                          icon={faTriangleExclamation}
                                          className="h-3.5 w-3.5"
                                        />
                                      )}
                                    </span>
                                  </Tooltip>
                                </td>
                                <td className="px-4 py-2">
                                  <div className="flex items-center gap-2">
                                    <Tooltip label={t("view")}>
                                      <button
                                        className="inline-flex h-8 w-8 items-center justify-center rounded-none bg-indigo-100 text-indigo-700 dark:bg-indigo-900/30 dark:text-indigo-200"
                                        onClick={() =>
                                          navigate(`/products/${product.id}`)
                                        }
                                        aria-label={t("view")}
                                      >
                                        <FontAwesomeIcon
                                          icon={faEye}
                                          className="h-4 w-4"
                                        />
                                      </button>
                                    </Tooltip>
                                    <Tooltip label={t("edit")}>
                                      <button
                                        className="inline-flex h-8 w-8 items-center justify-center rounded-none bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-200"
                                        onClick={() =>
                                          handleEditProduct(product)
                                        }
                                        aria-label={t("edit")}
                                      >
                                        <FontAwesomeIcon
                                          icon={faPenToSquare}
                                          className="h-4 w-4"
                                        />
                                      </button>
                                    </Tooltip>
                                    <Tooltip label={t("delete")}>
                                      <button
                                        className="inline-flex h-8 w-8 items-center justify-center rounded-none bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-200"
                                        onClick={() =>
                                          handleDeleteProduct(product.id)
                                        }
                                        aria-label={t("delete")}
                                      >
                                        <FontAwesomeIcon
                                          icon={faTrashCan}
                                          className="h-4 w-4"
                                        />
                                      </button>
                                    </Tooltip>
                                  </div>
                                </td>
                              </tr>
                            );
                          })
                        ) : (
                          <tr>
                            <td
                              colSpan={5}
                              className="px-4 py-8 text-center text-gray-500 dark:text-gray-400"
                            >
                              {hasActiveProductFilters
                                ? t("noResultsFound")
                                : t("noProductsInCategory")}
                            </td>
                          </tr>
                        )}
                      </tbody>
                    </table>
                  </div>
                </div>

                <div className="flex flex-wrap items-center justify-between gap-3">
                  <p className="text-sm text-gray-600 dark:text-gray-400">
                    {t("showing")} {productsResponse?.from || 0} -{" "}
                    {productsResponse?.to || 0} {t("of")}{" "}
                    {productsResponse?.total || 0}
                  </p>
                  <div className="flex flex-wrap items-center gap-2">
                    <select
                      value={perPage}
                      onChange={(event) => {
                        setPerPage(Number(event.target.value));
                        setPage(1);
                      }}
                      className="input h-9 py-0 w-auto min-w-[96px] px-2"
                      aria-label={t("perPage")}
                    >
                      <option value={10}>10 / {t("page")}</option>
                      <option value={20}>20 / {t("page")}</option>
                      <option value={50}>50 / {t("page")}</option>
                    </select>
                    <div className="flex items-center gap-1">
                      <input
                        type="number"
                        min={1}
                        value={quickGoPage}
                        onChange={(event) => setQuickGoPage(event.target.value)}
                        onKeyDown={(event) => {
                          if (event.key === "Enter") {
                            event.preventDefault();
                            handleQuickGoToPage();
                          }
                        }}
                        placeholder={t("quickGoToPage")}
                        className="input w-28"
                      />
                      <button
                        type="button"
                        onClick={handleQuickGoToPage}
                        className="btn-secondary rounded text-sm px-2.5"
                      >
                        {t("go")}
                      </button>
                    </div>
                    <Tooltip label={t("previous")}>
                      <button
                        type="button"
                        disabled={!productsResponse?.prev_page_url}
                        onClick={() =>
                          setPage((previous) => Math.max(previous - 1, 1))
                        }
                        className="inline-flex h-9 w-9 items-center justify-center rounded-none border border-gray-300 dark:border-gray-700 disabled:opacity-50"
                        aria-label={t("previous")}
                      >
                        <FontAwesomeIcon
                          icon={faChevronLeft}
                          className="h-4 w-4"
                        />
                      </button>
                    </Tooltip>
                    {buildPagination(
                      productsResponse?.current_page || 1,
                      productsResponse?.last_page || 1,
                    ).map((pageItem) => {
                      if (typeof pageItem === "string") {
                        return (
                          <span
                            key={pageItem}
                            className="px-2 text-sm text-gray-400"
                          >
                            ...
                          </span>
                        );
                      }

                      const isActive =
                        pageItem === (productsResponse?.current_page || 1);

                      return (
                        <button
                          key={pageItem}
                          type="button"
                          onClick={() => setPage(pageItem)}
                          className={`min-w-9 px-3 py-1.5 rounded border text-sm ${
                            isActive
                              ? "border-primary-500 bg-primary-50 dark:bg-primary-900/30"
                              : "border-gray-300 dark:border-gray-700"
                          }`}
                        >
                          {pageItem}
                        </button>
                      );
                    })}
                    <span className="text-sm text-gray-700 dark:text-gray-300">
                      {productsResponse?.current_page || 1} /{" "}
                      {productsResponse?.last_page || 1}
                    </span>
                    <Tooltip label={t("next")}>
                      <button
                        type="button"
                        disabled={!productsResponse?.next_page_url}
                        onClick={() =>
                          setPage((previous) =>
                            Math.min(
                              previous + 1,
                              productsResponse?.last_page || previous + 1,
                            ),
                          )
                        }
                        className="inline-flex h-9 w-9 items-center justify-center rounded-none border border-gray-300 dark:border-gray-700 disabled:opacity-50"
                        aria-label={t("next")}
                      >
                        <FontAwesomeIcon
                          icon={faChevronRight}
                          className="h-4 w-4"
                        />
                      </button>
                    </Tooltip>
                  </div>
                </div>
              </>
            ) : (
              <div className="rounded-xl border border-dashed border-gray-300 dark:border-gray-700 p-10 text-center text-gray-500 dark:text-gray-400">
                {t("selectCategoryHint")}
              </div>
            )}
          </div>
        </div>
      ) : (
        <div className="card text-center py-12">
          <p className="text-gray-600 dark:text-gray-400">
            {t("noCategories")}
          </p>
        </div>
      )}

      {showProductModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="card max-w-4xl w-full max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                {editingProduct ? t("editProduct") : t("addProduct")}
              </h3>
              <Tooltip label={t("close")}>
                <button
                  onClick={handleCloseProductModal}
                  aria-label={t("close")}
                  className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors duration-200"
                >
                  <FontAwesomeIcon icon={faXmark} className="h-4 w-4" />
                </button>
              </Tooltip>
            </div>
            <ProductForm
              product={editingProduct}
              defaultCategoryId={selectedCategoryId}
              lockCategory={!editingProduct}
              onSubmit={handleProductSubmit}
              onCancel={handleCloseProductModal}
              isLoading={
                createProductMutation.isPending ||
                updateProductMutation.isPending
              }
              hidePricingQuantity
              showAdvancedFields
            />
          </div>
        </div>
      )}

      {showCategoryModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="card max-w-lg w-full max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                {editingCategory ? t("editCategory") : t("addCategory")}
              </h3>
              <Tooltip label={t("close")}>
                <button
                  onClick={() => {
                    setShowCategoryModal(false);
                    setEditingCategory(null);
                  }}
                  aria-label={t("close")}
                  className="p-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors duration-200"
                >
                  <FontAwesomeIcon icon={faXmark} className="h-4 w-4" />
                </button>
              </Tooltip>
            </div>
            <form className="space-y-4" onSubmit={submitCategory}>
              <div>
                <label className="label">{t("categoryName")} *</label>
                <input
                  className="input"
                  value={categoryForm.name}
                  onChange={(event) =>
                    setCategoryForm((previous) => ({
                      ...previous,
                      name: event.target.value,
                    }))
                  }
                  required
                />
              </div>
              <div>
                <label className="label">{t("description")}</label>
                <textarea
                  className="input min-h-[88px]"
                  value={categoryForm.description}
                  onChange={(event) =>
                    setCategoryForm((previous) => ({
                      ...previous,
                      description: event.target.value,
                    }))
                  }
                />
              </div>
              <div>
                <label className="label">{t("parentCategory")}</label>
                <select
                  className="input"
                  value={categoryForm.parent_id}
                  onChange={(event) =>
                    setCategoryForm((previous) => ({
                      ...previous,
                      parent_id: event.target.value,
                    }))
                  }
                >
                  <option value="">{t("noParentRoot")}</option>
                  {categoriesResponse?.data?.map((category) => (
                    <option key={category.id} value={category.id}>
                      {category.name}
                    </option>
                  ))}
                </select>
              </div>
              <div className="flex justify-end gap-2 pt-2">
                <button
                  type="button"
                  className="btn-secondary"
                  onClick={() => {
                    setShowCategoryModal(false);
                    setEditingCategory(null);
                  }}
                >
                  {t("cancel")}
                </button>
                <button
                  type="submit"
                  className="btn-primary"
                  disabled={
                    createCategoryMutation.isPending ||
                    updateCategoryMutation.isPending
                  }
                >
                  {editingCategory ? t("update") : t("save")}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      <ConfirmationModal
        isOpen={showDeleteProductModal}
        onClose={() => {
          setShowDeleteProductModal(false);
          setProductToDelete(null);
        }}
        onConfirm={confirmDeleteProduct}
        title={t("confirmDeleteProduct")}
        message={t("confirmDeleteProduct")}
        confirmText={t("delete")}
        cancelText={t("cancel")}
        type="danger"
      />

      <ConfirmationModal
        isOpen={showDeleteCategoryModal}
        onClose={() => {
          setShowDeleteCategoryModal(false);
          setCategoryToDelete(null);
        }}
        onConfirm={confirmDeleteCategory}
        title={t("confirmDeleteCategory")}
        message={t("confirmDeleteCategory")}
        confirmText={t("delete")}
        cancelText={t("cancel")}
        type="danger"
      />
    </div>
  );
}

export default Products;

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useI18n } from "../context/I18nContext";
import api from "../services/api";

function ProfitLoss() {
  const { t } = useI18n();
  const [viewType, setViewType] = useState("summary"); // summary, daily, monthly, byProduct, byCategory
  const now = new Date();
  const [date, setDate] = useState(now.toISOString().split("T")[0]);
  const [month, setMonth] = useState(now.getMonth() + 1);
  const [year, setYear] = useState(now.getFullYear());
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const [fromDate, setFromDate] = useState(
    startOfMonth.toISOString().split("T")[0],
  );
  const [toDate, setToDate] = useState(now.toISOString().split("T")[0]);
  const [productId, setProductId] = useState("");
  const [categoryId, setCategoryId] = useState("");

  // جلب الملخص
  const { data: summaryData, isLoading: summaryLoading } = useQuery({
    queryKey: ["profit-loss-summary", fromDate, toDate],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (fromDate) params.append("from", fromDate);
      if (toDate) params.append("to", toDate);
      const response = await api.get(
        `/profit-loss/summary?${params.toString()}`,
      );
      return response.data;
    },
    enabled: viewType === "summary",
  });

  // جلب الأرباح اليومية
  const { data: dailyData, isLoading: dailyLoading } = useQuery({
    queryKey: ["profit-loss-daily", date],
    queryFn: async () => {
      const response = await api.get(`/profit-loss/daily?date=${date}`);
      return response.data;
    },
    enabled: viewType === "daily",
  });

  // جلب الأرباح الشهرية
  const { data: monthlyData, isLoading: monthlyLoading } = useQuery({
    queryKey: ["profit-loss-monthly", month, year],
    queryFn: async () => {
      const response = await api.get(
        `/profit-loss/monthly?month=${month}&year=${year}`,
      );
      return response.data;
    },
    enabled: viewType === "monthly",
  });

  // جلب الأرباح حسب المنتج
  const { data: byProductData, isLoading: byProductLoading } = useQuery({
    queryKey: ["profit-loss-by-product", productId, fromDate, toDate],
    queryFn: async () => {
      const params = new URLSearchParams();
      params.append("product_id", productId);
      if (fromDate) params.append("from", fromDate);
      if (toDate) params.append("to", toDate);
      const response = await api.get(
        `/profit-loss/by-product?${params.toString()}`,
      );
      return response.data;
    },
    enabled: viewType === "byProduct" && productId !== "",
  });

  // جلب الأرباح حسب القسم
  const { data: byCategoryData, isLoading: byCategoryLoading } = useQuery({
    queryKey: ["profit-loss-by-category", categoryId, fromDate, toDate],
    queryFn: async () => {
      const params = new URLSearchParams();
      params.append("category_id", categoryId);
      if (fromDate) params.append("from", fromDate);
      if (toDate) params.append("to", toDate);
      const response = await api.get(
        `/profit-loss/by-category?${params.toString()}`,
      );
      return response.data;
    },
    enabled: viewType === "byCategory" && categoryId !== "",
  });

  // جلب المنتجات
  const { data: productsData } = useQuery({
    queryKey: ["products"],
    queryFn: async () => {
      const response = await api.get("/products?per_page=100");
      return response.data;
    },
    enabled: viewType === "byProduct",
  });

  // جلب الأقسام
  const { data: categoriesData } = useQuery({
    queryKey: ["categories"],
    queryFn: async () => {
      const response = await api.get("/categories");
      return response.data;
    },
    enabled: viewType === "byCategory",
  });

  const formatCurrency = (amount) => {
    return `${parseFloat(amount).toFixed(2)} ر.س`;
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("ar-SA", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const isLoading =
    summaryLoading ||
    dailyLoading ||
    monthlyLoading ||
    byProductLoading ||
    byCategoryLoading;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">
            {t("loading")}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header Section (Title + Description + Quick Actions) */}
      <div className="page-header-section">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
            {t("profitLoss")}
          </h2>
          <p className="page-header-description">
            {t("profitLossDescription")}
          </p>
        </div>

        <div className="page-header-actions">
          <button
            onClick={() => setViewType("summary")}
            className={`px-4 py-1.5 rounded-lg transition-colors ${
              viewType === "summary"
                ? "bg-primary-600 text-white"
                : "bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-300 dark:hover:bg-gray-600"
            }`}
          >
            {t("summary")}
          </button>
          <button
            onClick={() => setViewType("daily")}
            className={`px-4 py-1.5 rounded-lg transition-colors ${
              viewType === "daily"
                ? "bg-primary-600 text-white"
                : "bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-300 dark:hover:bg-gray-600"
            }`}
          >
            {t("daily")}
          </button>
          <button
            onClick={() => setViewType("monthly")}
            className={`px-4 py-1.5 rounded-lg transition-colors ${
              viewType === "monthly"
                ? "bg-primary-600 text-white"
                : "bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-300 dark:hover:bg-gray-600"
            }`}
          >
            {t("monthly")}
          </button>
          <button
            onClick={() => setViewType("byProduct")}
            className={`px-4 py-1.5 rounded-lg transition-colors ${
              viewType === "byProduct"
                ? "bg-primary-600 text-white"
                : "bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-300 dark:hover:bg-gray-600"
            }`}
          >
            {t("byProduct")}
          </button>
          <button
            onClick={() => setViewType("byCategory")}
            className={`px-4 py-1.5 rounded-lg transition-colors ${
              viewType === "byCategory"
                ? "bg-primary-600 text-white"
                : "bg-gray-200 dark:bg-gray-700 text-gray-700 dark:text-gray-300 hover:bg-gray-300 dark:hover:bg-gray-600"
            }`}
          >
            {t("byCategory")}
          </button>
        </div>
      </div>

      {/* Filters */}
      {viewType === "summary" && (
        <div className="card">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="label">{t("fromDate")}</label>
              <input
                type="date"
                value={fromDate}
                onChange={(e) => setFromDate(e.target.value)}
                className="input"
              />
            </div>
            <div>
              <label className="label">{t("toDate")}</label>
              <input
                type="date"
                value={toDate}
                onChange={(e) => setToDate(e.target.value)}
                className="input"
              />
            </div>
          </div>
        </div>
      )}

      {viewType === "daily" && (
        <div className="card">
          <div>
            <label className="label">{t("date")}</label>
            <input
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="input"
            />
          </div>
        </div>
      )}

      {viewType === "monthly" && (
        <div className="card">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="label">{t("month")}</label>
              <select
                value={month}
                onChange={(e) => setMonth(parseInt(e.target.value))}
                className="input"
              >
                {Array.from({ length: 12 }, (_, i) => i + 1).map((m) => (
                  <option key={m} value={m}>
                    {new Date(2000, m - 1).toLocaleString("ar-SA", {
                      month: "long",
                    })}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="label">{t("year")}</label>
              <input
                type="number"
                value={year}
                onChange={(e) => setYear(parseInt(e.target.value))}
                className="input"
                min="2020"
                max={new Date().getFullYear()}
              />
            </div>
          </div>
        </div>
      )}

      {viewType === "byProduct" && (
        <div className="card">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="label">{t("product")}</label>
              <select
                value={productId}
                onChange={(e) => setProductId(e.target.value)}
                className="input"
              >
                <option value="">{t("selectProduct")}</option>
                {productsData?.data?.map((product) => (
                  <option key={product.id} value={product.id}>
                    {product.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="label">{t("fromDate")}</label>
              <input
                type="date"
                value={fromDate}
                onChange={(e) => setFromDate(e.target.value)}
                className="input"
              />
            </div>
            <div>
              <label className="label">{t("toDate")}</label>
              <input
                type="date"
                value={toDate}
                onChange={(e) => setToDate(e.target.value)}
                className="input"
              />
            </div>
          </div>
        </div>
      )}

      {viewType === "byCategory" && (
        <div className="card">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="label">{t("category")}</label>
              <select
                value={categoryId}
                onChange={(e) => setCategoryId(e.target.value)}
                className="input"
              >
                <option value="">{t("selectCategory")}</option>
                {categoriesData?.data?.map((category) => (
                  <option key={category.id} value={category.id}>
                    {category.name}
