                {t("totalSales")}
              </h3>
              <p className="text-2xl font-bold text-blue-900 dark:text-blue-200">
                {formatCurrency(summaryData.data.sales || 0)}
              </p>
            </div>
            <div className="card bg-gradient-to-br from-red-50 to-red-100 dark:from-red-900/20 dark:to-red-800/20 border-red-200 dark:border-red-800">
              <h3 className="text-sm font-medium text-red-800 dark:text-red-300 mb-1">
                {t("costOfGoods")}
              </h3>
              <p className="text-2xl font-bold text-red-900 dark:text-red-200">
                {formatCurrency(summaryData.data.cost_of_goods || 0)}
              </p>
            </div>
            <div className="card bg-gradient-to-br from-green-50 to-green-100 dark:from-green-900/20 dark:to-green-800/20 border-green-200 dark:border-green-800">
              <h3 className="text-sm font-medium text-green-800 dark:text-green-300 mb-1">
                {t("grossProfit")}
              </h3>
              <p className="text-2xl font-bold text-green-900 dark:text-green-200">
                {formatCurrency(summaryData.data.gross_profit || 0)}
              </p>
            </div>
            <div
              className={`card bg-gradient-to-br ${
                (summaryData.data.net_profit || 0) >= 0
                  ? "from-green-50 to-green-100 dark:from-green-900/20 dark:to-green-800/20 border-green-200 dark:border-green-800"
                  : "from-red-50 to-red-100 dark:from-red-900/20 dark:to-red-800/20 border-red-200 dark:border-red-800"
              }`}
            >
              <h3
                className="text-sm font-medium mb-1 ${
                (summaryData.data.net_profit || 0) >= 0
                  ? 'text-green-800 dark:text-green-300'
                  : 'text-red-800 dark:text-red-300'
              }"
              >
                {t("netProfit")}
              </h3>
              <p
                className={`text-2xl font-bold ${
                  (summaryData.data.net_profit || 0) >= 0
                    ? "text-green-900 dark:text-green-200"
                    : "text-red-900 dark:text-red-200"
                }`}
              >
                {formatCurrency(summaryData.data.net_profit || 0)}
              </p>
            </div>
          </div>

          {/* Details */}
          <div className="card">
            <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
              {t("details")}
            </h3>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {t("expenses")}
                </p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  {formatCurrency(summaryData.data.expenses || 0)}
                </p>
              </div>
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {t("returns")}
                </p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  {formatCurrency(summaryData.data.returns || 0)}
                </p>
              </div>
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {t("salesCount")}
                </p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  {summaryData.data.statistics?.sales_count || 0}
                </p>
              </div>
              <div>
                <p className="text-sm text-gray-600 dark:text-gray-400">
                  {t("expensesCount")}
                </p>
                <p className="text-lg font-semibold text-gray-900 dark:text-white">
                  {summaryData.data.statistics?.expenses_count || 0}
                </p>
              </div>
            </div>
          </div>

          {/* By Category */}
          {summaryData.data.by_category &&
            summaryData.data.by_category.length > 0 && (
              <div className="card">
                <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
                  {t("byCategory")}
                </h3>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead className="bg-gray-50 dark:bg-gray-800">
                      <tr>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                          {t("category")}
                        </th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                          {t("sales")}
                        </th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                          {t("costOfGoods")}
                        </th>
                        <th className="px-4 py-2 text-right text-xs font-medium text-gray-500 dark:text-gray-400">
                          {t("grossProfit")}
                        </th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                      {summaryData.data.by_category.map((item) => (
                        <tr key={item.category_id}>
                          <td className="px-4 py-2 text-sm text-gray-900 dark:text-white">
                            {item.category_name}
                          </td>
                          <td className="px-4 py-2 text-sm text-gray-600 dark:text-gray-400">
                            {formatCurrency(item.sales || 0)}
                          </td>
                          <td className="px-4 py-2 text-sm text-gray-600 dark:text-gray-400">
                            {formatCurrency(item.cost_of_goods || 0)}
                          </td>
                          <td
                            className={`px-4 py-2 text-sm font-semibold ${
                              (item.gross_profit || 0) >= 0
                                ? "text-green-600 dark:text-green-400"
                                : "text-red-600 dark:text-red-400"
                            }`}
                          >
                            {formatCurrency(item.gross_profit || 0)}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            )}
        </div>
      )}

      {/* Daily View */}
      {viewType === "daily" && dailyData?.data && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="card">
              <h3 className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
                {t("sales")}
              </h3>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {formatCurrency(dailyData.data.sales || 0)}
              </p>
            </div>
            <div className="card">
              <h3 className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
                {t("grossProfit")}
              </h3>
              <p className="text-2xl font-bold text-green-600 dark:text-green-400">
                {formatCurrency(dailyData.data.gross_profit || 0)}
              </p>
            </div>
            <div
              className={`card ${
                (dailyData.data.net_profit || 0) >= 0
                  ? "bg-green-50 dark:bg-green-900/20"
                  : "bg-red-50 dark:bg-red-900/20"
              }`}
            >
              <h3 className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
                {t("netProfit")}
              </h3>
              <p
                className={`text-2xl font-bold ${
                  (dailyData.data.net_profit || 0) >= 0
                    ? "text-green-600 dark:text-green-400"
                    : "text-red-600 dark:text-red-400"
                }`}
              >
                {formatCurrency(dailyData.data.net_profit || 0)}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Monthly View */}
      {viewType === "monthly" && monthlyData?.data && (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="card">
              <h3 className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
                {t("sales")}
              </h3>
              <p className="text-2xl font-bold text-gray-900 dark:text-white">
                {formatCurrency(monthlyData.data.sales || 0)}
              </p>
            </div>
            <div className="card">
              <h3 className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
                {t("grossProfit")}
              </h3>
              <p className="text-2xl font-bold text-green-600 dark:text-green-400">
                {formatCurrency(monthlyData.data.gross_profit || 0)}
              </p>
            </div>
            <div
              className={`card ${
                (monthlyData.data.net_profit || 0) >= 0
                  ? "bg-green-50 dark:bg-green-900/20"
                  : "bg-red-50 dark:bg-red-900/20"
              }`}
            >
              <h3 className="text-sm font-medium text-gray-600 dark:text-gray-400 mb-1">
                {t("netProfit")}
              </h3>
              <p
                className={`text-2xl font-bold ${
                  (monthlyData.data.net_profit || 0) >= 0
                    ? "text-green-600 dark:text-green-400"
                    : "text-red-600 dark:text-red-400"
                }`}
              >
                {formatCurrency(monthlyData.data.net_profit || 0)}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* By Product View */}
      {viewType === "byProduct" && byProductData?.data && (
        <div className="card">
          <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
            {byProductData.data.product?.name}
          </h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {t("quantitySold")}
              </p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {byProductData.data.quantity_sold || 0}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {t("sales")}
              </p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(byProductData.data.sales || 0)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {t("costOfGoods")}
              </p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(byProductData.data.cost_of_goods || 0)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {t("grossProfit")}
              </p>
              <p
                className={`text-lg font-semibold ${
                  (byProductData.data.gross_profit || 0) >= 0
                    ? "text-green-600 dark:text-green-400"
                    : "text-red-600 dark:text-red-400"
                }`}
              >
                {formatCurrency(byProductData.data.gross_profit || 0)}
              </p>
            </div>
          </div>
        </div>
      )}

      {/* By Category View */}
      {viewType === "byCategory" && byCategoryData?.data && (
        <div className="card">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {t("productsSold")}
              </p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {byCategoryData.data.products_sold || 0}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {t("sales")}
              </p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(byCategoryData.data.sales || 0)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {t("costOfGoods")}
              </p>
              <p className="text-lg font-semibold text-gray-900 dark:text-white">
                {formatCurrency(byCategoryData.data.cost_of_goods || 0)}
              </p>
            </div>
            <div>
              <p className="text-sm text-gray-600 dark:text-gray-400">
                {t("grossProfit")}
              </p>
              <p
                className={`text-lg font-semibold ${
                  (byCategoryData.data.gross_profit || 0) >= 0
                    ? "text-green-600 dark:text-green-400"
                    : "text-red-600 dark:text-red-400"
                }`}
              >
                {formatCurrency(byCategoryData.data.gross_profit || 0)}
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ProfitLoss;

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useI18n } from "../context/I18nContext";
import { toast } from "react-hot-toast";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faFilePdf } from "@fortawesome/free-solid-svg-icons";
import api from "../services/api";

function Reports() {
  const { t } = useI18n();
  const [reportType, setReportType] = useState("bestSelling"); // bestSelling, worstSelling, salesByTime, expiredLosses, inventory, financial, monthlyComparison
  const [period, setPeriod] = useState("monthly"); // daily, monthly
  const [date, setDate] = useState(new Date().toISOString().split("T")[0]);
  const now = new Date();
  const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
  const [fromDate, setFromDate] = useState(
    startOfMonth.toISOString().split("T")[0],
  );
  const [toDate, setToDate] = useState(now.toISOString().split("T")[0]);

  // Monthly Comparison
  const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
  const [month1, setMonth1] = useState(lastMonth.toISOString().slice(0, 7));
  const [month2, setMonth2] = useState(now.toISOString().slice(0, 7));

  // جلب أفضل المنتجات مبيعًا
  const { data: bestSellingData, isLoading: bestSellingLoading } = useQuery({
    queryKey: ["reports-best-selling", period],
    queryFn: async () => {
      const response = await api.get(`/reports/best-selling?period=${period}`);
      return response.data;
    },
    enabled: reportType === "bestSelling",
  });

  // جلب المنتجات الضعيفة
  const { data: worstSellingData, isLoading: worstSellingLoading } = useQuery({
    queryKey: ["reports-worst-selling", period],
    queryFn: async () => {
      const response = await api.get(`/reports/worst-selling?period=${period}`);
      return response.data;
    },
    enabled: reportType === "worstSelling",
  });

  // جلب مبيعات حسب الوقت
  const { data: salesByTimeData, isLoading: salesByTimeLoading } = useQuery({
    queryKey: ["reports-sales-by-time", date],
    queryFn: async () => {
      const response = await api.get(`/reports/sales-by-time?date=${date}`);
      return response.data;
    },
    enabled: reportType === "salesByTime",
  });

  // جلب خسائر الصلاحية
  const { data: expiredLossesData, isLoading: expiredLossesLoading } = useQuery(
    {
      queryKey: ["reports-expired-losses", fromDate, toDate],
      queryFn: async () => {
        const params = new URLSearchParams();
        if (fromDate) params.append("from", fromDate);
        if (toDate) params.append("to", toDate);
        const response = await api.get(
          `/reports/expired-losses?${params.toString()}`,
        );
        return response.data;
      },
      enabled: reportType === "expiredLosses",
    },
  );

  // جلب تقارير المخزون
  const { data: inventoryData, isLoading: inventoryLoading } = useQuery({
    queryKey: ["reports-inventory", fromDate, toDate],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (fromDate) params.append("from", fromDate);
      if (toDate) params.append("to", toDate);
      const response = await api.get(`/reports/inventory?${params.toString()}`);
      return response.data;
    },
    enabled: reportType === "inventory",
  });

  // جلب التقارير المالية
  const { data: financialData, isLoading: financialLoading } = useQuery({
    queryKey: ["reports-financial", fromDate, toDate],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (fromDate) params.append("from", fromDate);
      if (toDate) params.append("to", toDate);
      const response = await api.get(`/reports/financial?${params.toString()}`);
      return response.data;
    },
    enabled: reportType === "financial",
  });

  // جلب مقارنة شهرية
  const { data: monthlyComparisonData, isLoading: monthlyComparisonLoading } =
    useQuery({
      queryKey: ["reports-monthly-comparison", month1, month2],
      queryFn: async () => {
        const params = new URLSearchParams();
        params.append("month1", month1);
        params.append("month2", month2);
        const response = await api.get(
          `/reports/monthly-comparison?${params.toString()}`,
        );
        return response.data;
      },
      enabled: reportType === "monthlyComparison",
    });

  // تصدير PDF
  const handleExportPDF = async () => {
    try {
      const params = new URLSearchParams();
      params.append("type", reportType);

      if (reportType === "bestSelling" || reportType === "worstSelling") {
        params.append("period", period);
      } else if (reportType === "salesByTime") {
        params.append("date", date);
      } else if (
        reportType === "expiredLosses" ||
        reportType === "inventory" ||
        reportType === "financial"
      ) {
        if (fromDate) params.append("from", fromDate);
        if (toDate) params.append("to", toDate);
      }

      const response = await api.get(
        `/reports/export/pdf?${params.toString()}`,
        {
          responseType: "blob",
        },
      );

      // إنشاء رابط تحميل
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute(
        "download",
        `report_${reportType}_${new Date().toISOString().split("T")[0]}.pdf`,
      );
      document.body.appendChild(link);
      link.click();
      link.remove();
      toast.success(t("exportPDF") || "PDF exported successfully");
    } catch (error) {
      toast.error(t("exportError") || "Error exporting PDF");
    }
  };

  const formatCurrency = (amount) => {
    return `${parseFloat(amount).toFixed(2)} ر.س`;
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("ar-SA", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  };

  const isLoading =
    bestSellingLoading ||
    worstSellingLoading ||
    salesByTimeLoading ||
    expiredLossesLoading ||
    inventoryLoading ||
    financialLoading ||
    monthlyComparisonLoading;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">
            {t("loading")}
          </p>
        </div>
      </div>
