import { useState, useEffect } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useI18n } from "../context/I18nContext";
import toast from "react-hot-toast";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faPenToSquare,
  faPlus,
  faTrashCan,
  faTriangleExclamation,
  faUsers,
  faXmark,
  faKey,
} from "@fortawesome/free-solid-svg-icons";
import ConfirmationModal from "../components/ConfirmationModal";
import api from "../services/api";

function Roles() {
  const { t } = useI18n();
  const queryClient = useQueryClient();
  const [showModal, setShowModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [showPermissionsModal, setShowPermissionsModal] = useState(false);
  const [selectedRole, setSelectedRole] = useState(null);
  const [roleToDelete, setRoleToDelete] = useState(null);
  const [editingRole, setEditingRole] = useState(null);
  const [formData, setFormData] = useState({
    name: "",
    permissions: [],
  });

  // جلب الرول
  const {
    data: rolesData,
    isLoading: rolesLoading,
    error: rolesError,
  } = useQuery({
    queryKey: ["roles"],
    queryFn: async () => {
      try {
        const response = await api.get("/roles");
        console.log("Roles API Response:", response.data);
        // معالجة البيانات بشكل صحيح
        if (response.data?.data) {
          return Array.isArray(response.data.data) ? response.data.data : [];
        }
        if (Array.isArray(response.data)) {
          return response.data;
        }
        return [];
      } catch (error) {
        console.error("Error fetching roles:", error);
        // معالجة أخطاء الرول بشكل خاص
        if (error.response?.status === 403) {
          toast.error(
            t("noPermissionToViewRoles") ||
              "You do not have permission to view roles. Please contact your administrator.",
          );
        } else {
          toast.error(t("errorLoadingRoles") || "Error loading roles");
        }
        throw error; // إعادة رمي الخطأ لـ react-query
      }
    },
  });

  // جلب الصلاحيات
  const {
    data: permissionsData,
    isLoading: permissionsLoading,
    error: permissionsError,
  } = useQuery({
    queryKey: ["permissions"],
    queryFn: async () => {
      try {
        const response = await api.get("/permissions");
        console.log("Permissions API Response:", response.data);
        // معالجة البيانات بشكل صحيح
        if (response.data?.data) {
          return typeof response.data.data === "object"
            ? response.data.data
            : {};
        }
        if (
          typeof response.data === "object" &&
          !Array.isArray(response.data)
        ) {
          return response.data;
        }
        return {};
      } catch (error) {
        console.error("Error fetching permissions:", error);
        // معالجة أخطاء الصلاحيات بشكل خاص
        if (error.response?.status === 403) {
          toast.error(
            t("noPermissionToViewPermissions") ||
              "You do not have permission to view permissions. Please contact your administrator.",
          );
        } else {
          toast.error(
            t("errorLoadingPermissions") || "Error loading permissions",
          );
        }
        throw error; // إعادة رمي الخطأ لـ react-query
      }
    },
  });

  // إضافة رول
  const createMutation = useMutation({
    mutationFn: async (data) => {
      const response = await api.post("/roles", data);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["roles"]);
      setShowModal(false);
      setFormData({ name: "", permissions: [] });
      setEditingRole(null);
      toast.success(
        t("roleCreatedSuccessfully") || "Role created successfully",
      );
    },
    onError: (error) => {
      const message =
        error.response?.data?.message ||
        (error.response?.data?.errors
          ? Object.values(error.response.data.errors).flat().join(", ")
          : null) ||
        t("errorCreatingRole") ||
        "Error creating role";
      toast.error(message);
    },
  });

  // تحديث رول
  const updateMutation = useMutation({
    mutationFn: async ({ id, data }) => {
      const response = await api.put(`/roles/${id}`, data);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["roles"]);
      setShowModal(false);
      setFormData({ name: "", permissions: [] });
      setEditingRole(null);
      toast.success(
        t("roleUpdatedSuccessfully") || "Role updated successfully",
      );
    },
    onError: (error) => {
      const message =
        error.response?.data?.message ||
        (error.response?.data?.errors
          ? Object.values(error.response.data.errors).flat().join(", ")
          : null) ||
        t("errorUpdatingRole") ||
        "Error updating role";
      toast.error(message);
    },
  });

  // حذف رول
  const deleteMutation = useMutation({
    mutationFn: async (id) => {
      const response = await api.delete(`/roles/${id}`);
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries(["roles"]);
      toast.success(
        t("roleDeletedSuccessfully") || "Role deleted successfully",
      );
    },
    onError: (error) => {
      const message =
        error.response?.data?.message ||
        t("errorDeletingRole") ||
        "Error deleting role";
      toast.error(message);
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    const submitData = {
      name: formData.name,
      permissions: formData.permissions.map((p) =>
        typeof p === "object" ? p.id : p,
      ),
    };

    if (editingRole) {
      updateMutation.mutate({ id: editingRole.id, data: submitData });
    } else {
      createMutation.mutate(submitData);
    }
  };

  const handleEdit = (role) => {
    setEditingRole(role);
    setFormData({
      name: role.name,
      permissions: role.permissions?.map((p) => p.id) || [],
    });
    setShowModal(true);
  };

  const handleDelete = (id) => {
    setRoleToDelete(id);
    setShowDeleteModal(true);
  };

  const confirmDelete = () => {
    if (!roleToDelete) return;

    toast.promise(
      new Promise((resolve, reject) => {
        deleteMutation.mutate(roleToDelete, {
          onSuccess: () => resolve(),
          onError: (error) => reject(error),
        });
      }),
      {
        loading: t("deletingRole") || "Deleting role...",
        success: t("roleDeletedSuccessfully") || "Role deleted successfully",
        error: (err) =>
          err.response?.data?.message ||
          t("errorDeletingRole") ||
          "Error deleting role",
      },
    );

    setShowDeleteModal(false);
    setRoleToDelete(null);
  };

  const handleCloseModal = () => {
    setShowModal(false);
    setEditingRole(null);
    setFormData({ name: "", permissions: [] });
  };

  const togglePermission = (permissionId) => {
    setFormData((prev) => ({
      ...prev,
      permissions: prev.permissions.includes(permissionId)
        ? prev.permissions.filter((id) => id !== permissionId)
        : [...prev.permissions, permissionId],
    }));
  };

  const isLoading = rolesLoading || permissionsLoading;
  const roles = Array.isArray(rolesData) ? rolesData : [];
  const permissions =
    permissionsData &&
    typeof permissionsData === "object" &&
    !Array.isArray(permissionsData)
      ? permissionsData
      : {};

  // Debug: عرض البيانات في console
  useEffect(() => {
    if (!isLoading) {
      console.log("Roles Data:", roles);
      console.log("Permissions Data:", permissions);
      console.log("Roles Count:", roles.length);
      console.log("Permissions Groups:", Object.keys(permissions).length);
    }
  }, [roles, permissions, isLoading]);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
          <p className="mt-4 text-gray-600 dark:text-gray-400">
            {t("loading")}
          </p>
        </div>
      </div>
    );
  }

  if (rolesError || permissionsError) {
    return (
      <div className="card">
        <div className="text-center py-12">
          <div className="text-6xl mb-4">
            <FontAwesomeIcon icon={faTriangleExclamation} />
          </div>
          <h3 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
            {t("errorLoadingData") || "Error loading data"}
          </h3>
          <p className="text-gray-600 dark:text-gray-400 mb-6">
            {rolesError?.message ||
              permissionsError?.message ||
              "Please try again later"}
          </p>
          <button
            onClick={() => {
              queryClient.invalidateQueries(["roles"]);
              queryClient.invalidateQueries(["permissions"]);
            }}
            className="btn-primary"
          >
            {t("retry") || "Retry"}
          </button>
        </div>
      </div>
    );
  }

  return (
